function record(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}
export function resolveAppearancePreferences(
  value: unknown,
  defaults: AppearancePreferences = APPEARANCE_DEFAULTS,
): AppearancePreferences {
  const source = record(value) ? value : {};
  return Object.fromEntries(
    (Object.keys(APPEARANCE_OPTIONS) as (keyof AppearancePreferences)[]).map(
      (key) => [
        key,
        APPEARANCE_OPTIONS[key].some((option) => option.value === source[key])
          ? source[key]
          : defaults[key],
      ],
    ),
  ) as AppearancePreferences;
}
export function parseAppearancePreferences(
  value: unknown,
): AppearancePreferences | null {
  if (
    !record(value) ||
    !(Object.keys(APPEARANCE_OPTIONS) as (keyof AppearancePreferences)[]).every(
      (key) =>
        APPEARANCE_OPTIONS[key].some((option) => option.value === value[key]),
    )
  )
    return null;
  return resolveAppearancePreferences(value);
}
